    internal static int GtText(emon.Port.Cells txt, byte[] b) {
        // Append the bytes of `b` to `txt` as code points; answers the run's start.
        int s = emon.Port.CellsLen(txt);
        int n = emon.Port.BlobLen(b);
        int k = 0;
        while (k < n) {
            emon.Port.CellsPush(txt, emon.Port.BlobU8(b, k));
            k += 1;
        }
        return s;
    }
