        emon.Port.CellsSet(an, at + 23, -1);
        emon.Port.CellsSet(an, at + 24, 0);
        emon.Port.CellsSet(an, at + 27, -1);
        emon.Port.CellsSet(an, at + 28, 0);
        emon.Port.CellsSet(an, at + 32, -1);
        emon.Port.CellsSet(an, at + 33, 0);
        emon.Port.CellsSet(an, at + 34, -1);
        emon.Port.CellsSet(an, at + 35, 0);
        emon.Port.CellsSet(an, at + 30, bits);
        if (bits > 0) {
            emon.Port.CellsSet(an, at + 23, GtText(txt, emon.Testport.TextBlob("Zed Fox")));
            emon.Port.CellsSet(an, at + 24, 7);
            emon.Port.CellsSet(an, at + 27, GtText(txt, emon.Testport.TextBlob("ok")));
            emon.Port.CellsSet(an, at + 28, 2);
            emon.Port.CellsSet(an, at + 32, GtText(txt, emon.Testport.TextBlob("Rome")));
            emon.Port.CellsSet(an, at + 33, 4);
        }
        return at / 38;
    }
    [Xunit.Fact]
    public static void TestADigitalSignatureFieldIsACandidateWhetherSignedOrNot() {
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells fw = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells ow = emon.Port.NewCells();
        emon.Port.Cells an = emon.Port.NewCells();
        emon.Port.Cells txt = emon.Port.NewCells();
        emon.Port.Cells sm = emon.Port.NewCells();
        emon.Testport.AssertEq(Sigmark.SgHasDigital(an), 0, "no row, no digital signature");
        GtDigsig(an, txt, 0, 30000, 3, 2026, 16);
        GtDigsig(an, txt, 0, 50000, 0, -1, 0);
        emon.Testport.AssertEq(Sigmark.SgHasDigital(an), 1, "a row of the subtype");
        emon.Testport.AssertEq(GtFind(pa, pts, fw, et, ow, an, txt, 1, sm), 2, "a signed field and an unsigned one, on a page with no path at all");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 5), Player.PlsDigitalSignature(), "a digital signature");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 1), 19000, "its box is the widget's");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 12) & 256, 256, "the text run is a record (flag 256)");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 12) & 512, 512, "signed (flag 512)");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 7), -1, "it points at no path");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 15), -1, "and has no ink");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 9), 951, "a signed field is as sure as the file says");
        emon.Testport.AssertEq(Player.SlGet(sm, 1, 12) & 512, 0, "the second is not signed");
        emon.Testport.AssertEq(Player.SlGet(sm, 1, 9), 900, "and a little less sure");
        emon.Testport.AssertEq(Player.SlGet(sm, 1, 14), 3, "its record is only the three separators");
        // the record of the first: Zed Fox US ok US Rome US 2026-04-01T08:09:10Z
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 14), 36, "7 + 1 + 2 + 1 + 4 + 1 + 20 characters");
        emon.Testport.AssertEq(emon.Port.CellsAt(et, Player.SlGet(sm, 0, 13) + 7), 31, "the separator after the name");
    }
    [Xunit.Fact]
    public static void TestTheModelCarriesTheDigitalSignature() {
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells chk = emon.Port.NewCells();
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells fw = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells ow = emon.Port.NewCells();
        emon.Port.Cells an = emon.Port.NewCells();
        emon.Port.Cells txt = emon.Port.NewCells();
        emon.Port.Cells sm = emon.Port.NewCells();
        emon.Port.Cells nn = emon.Port.NewCells();
        emon.Port.Cells na = emon.Port.NewCells();
        emon.Port.Cells nr = emon.Port.NewCells();
        emon.Port.Cells nm = emon.Port.NewCells();
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        int sec = Model.NodeNew(nodes, Model.NkSection(), 0);
        int par = Model.NodeNew(nodes, Model.NkParagraph(), sec);
        Model.NodeAddRegion(nodes, regions, par, 1, 10000, 10000, 60000, 20000);
        GtDigsig(an, txt, 0, 30000, 3, 2026, 16);
        GtDigsig(an, txt, 0, 50000, 0, -1, 0);
        emon.Testport.AssertEq(GtFind(pa, pts, fw, et, ow, an, txt, 1, sm), 2, "two candidates");
        emon.Testport.AssertEq(Sealmark.SmWrite(sm, et, nodes, attrs, regions, text, nn, na, nr, nm), 2, "two nodes written");
        emon.Testport.AssertEq(Model.NodeKind(nn, 3), Model.NkSeal(), "the first seal node");
        emon.Testport.AssertEq(Model.NodeSub(nn, 3), Model.SlDigitalSignature(), "of the subkind digital-signature");
        int a = Model.NodeAttr(nn, na, 3, Model.FkName());
        int d = Model.NodeAttr(nn, na, 3, Model.FkDate());
        int r = Model.NodeAttr(nn, na, 3, Model.FkReason());
        int l = Model.NodeAttr(nn, na, 3, Model.FkLocation());
        int s = Model.NodeAttr(nn, na, 3, Model.FkSigned());
        int u = Model.NodeAttr(nn, na, 4, Model.FkSigned());
        int un = Model.NodeAttr(nn, na, 4, Model.FkName());
        emon.Testport.AssertEq(Model.AttrLen(na, a), 7, "the signer, Zed Fox");
        emon.Testport.AssertEq(emon.Port.CellsAt(text, Model.AttrValue(na, a)), 90, "which starts with Z");
        emon.Testport.AssertEq(Model.AttrLen(na, r), 2, "the reason, ok");
        emon.Testport.AssertEq(Model.AttrLen(na, l), 4, "the location, Rome");
        emon.Testport.AssertEq(Model.AttrLen(na, d), 20, "the time as ISO 8601 with its zone");
        emon.Testport.AssertEq(emon.Port.CellsAt(text, Model.AttrValue(na, d) + 19), 90, "ending in Z for UTC");
        emon.Testport.AssertEq(emon.Port.CellsAt(text, Model.AttrValue(na, d) + 10), 84, "with a T between the day and the hour");
        emon.Testport.AssertEq(Model.AttrValue(na, s), 1, "signed");
        emon.Testport.AssertEq(Model.AttrValue(na, u), 0, "the second is not");
        emon.Testport.AssertEq(Model.NodeAttr(nn, na, 4, Model.FkDate()), -1, "and says no date");
        emon.Testport.AssertEq(un, -1, "or name");
        emon.Testport.AssertEq(Model.ModelCheck(nn, na, nr, text, pages, ledger, layout, chk), 0, "and the Model still checks");
    }
